/** Hi-Res 无损音质按钮图标（B站控制栏原样） */
export const HiRes = (attrs: Record<string, unknown> = {}): VNode =>
  h("span", {
    class: "common-svg-icon",
    ...attrs,
    ref: (el: Element) => {
      const root = parseSvgMarkup(HIRES_MARKUP);
      if (root) el.appendChild(root);
    },
  });

/**
 * Issue 图标（既有实现原样复制）
 *
 * 这份图标带 defs + filter + 两个 use，不能走会过滤 use 的安全解析，
 * 也不适合逐条改写成虚拟节点（path/filter 参数多，手抄易错），
 * 因此保留原始标记文本，由函数 ref 在挂载时按原样解析后整颗挂上。
 */
export const Issue = (attrs: Record<string, unknown> = {}): VNode =>
  h("span", {
    class: "common-svg-icon",
    ...attrs,
    ref: (el: Element) => {
      const root = parseSvgMarkup(ISSUE_MARKUP);
      if (root) el.appendChild(root);
    },
  });
